#[test]
#[cfg(feature = "deflate-flate2")]
fn encrypting_file() {
    use std::io::{Read, Write};
    use zip::unstable::write::FileOptionsExt;
    let mut buf = vec![0; 2048];
    let mut archive = zip::write::ZipWriter::new(Cursor::new(&mut buf));
    archive
        .start_file(
            "name",
            zip::write::SimpleFileOptions::default().with_deprecated_encryption(b"password"),
        )
        .unwrap();
    archive.write_all(b"test").unwrap();
    archive.finish().unwrap();
    let mut archive = zip::ZipArchive::new(Cursor::new(&mut buf)).unwrap();
    let mut file = archive.by_index_decrypt(0, b"password").unwrap();
    let mut buf = Vec::new();
    file.read_to_end(&mut buf).unwrap();
    assert_eq!(buf, b"test");
}
#[test]
fn encrypted_file() {
    use std::io::Read;

    let zip_file_bytes = &mut Cursor::new(ZIP_CRYPTO_FILE);
    let mut archive = zip::ZipArchive::new(zip_file_bytes).unwrap();

    assert_eq!(archive.len(), 1); //Only one file inside archive: `test.txt`

    {
        // No password
        let file = archive.by_index(0);
        match file {
            Err(zip::result::ZipError::UnsupportedArchive(
                zip::result::ZipError::PASSWORD_REQUIRED,
            )) => (),
            Err(_) => panic!(
                "Expected PasswordRequired error when opening encrypted file without password"
            ),
            Ok(_) => panic!("Error: Successfully opened encrypted file without password?!"),
        }
    }

    {
        // Wrong password
        let file = archive.by_index_decrypt(0, b"wrong password");
        match file {
            Err(ZipError::InvalidPassword) => (),
            Err(_) => panic!(
                "Expected InvalidPassword error when opening encrypted file with wrong password"
            ),
            Ok(_) => panic!("Error: Successfully opened encrypted file with wrong password?!"),
        }
    }

    {
        // Correct password, read contents
        let mut file = archive.by_index_decrypt(0, "test".as_bytes()).unwrap();
        let file_name = file.enclosed_name().unwrap();
        assert_eq!(file_name, std::path::PathBuf::from("test.txt"));

        let mut data = Vec::new();
        file.read_to_end(&mut data).unwrap();
        assert_eq!(data, "abcdefghijklmnopqrstuvwxyz123456789".as_bytes());
    }
}

#[test]
fn buffered_read() {
    use std::io::{BufReader, Read};

    // delibirately pick a buffer capacity in a way that when `ZipCryptoReaderValid` read happens, it's not going to take entire buffer,
    // for this file it needs to be between 13..=46 bytes (with exception of 44 bytes)
    let zip_file_bytes = &mut Cursor::new(ZIP_CRYPTO_FILE);
    let buffered = BufReader::with_capacity(13, zip_file_bytes);
    let mut archive = zip::ZipArchive::new(buffered).unwrap();

    let mut file = archive.by_index_decrypt(0, b"test").unwrap();

    // should not panic with `Custom { kind: Other, error: "Invalid checksum" }`
    // or `Custom { kind: InvalidInput, error: "corrupt deflate stream" }`
    let mut data = Vec::new();
    file.read_to_end(&mut data).unwrap();
}
